INSERT INTO instruments (instrument_id, authority_id, lg_id, kind, force, title, notes) VALUES ($q$MBRC_PLANNING_SCHEME_2016$q$, $q$CMB$q$, $q$MORETON_BAY$q$, 'PLANNING_SCHEME', 'STATUTORY_INSTRUMENT', $q$Moreton Bay Regional Council Planning Scheme 2016 (MBRC Planning Scheme)$q$, $q$Scheme commenced 1 Feb 2016. eScheme (IsoPlan) API revision list (api/l/vpr): revisionId 96 'Version 8', revStatus 'Current', planOperative 09/11/2026 (MM/DD/YYYY = 11 Sep 2026); revisionId 90 'Version 7.1' operative 06/23/2025, Superseded. Citation (rule 202): 'Some parts of the original planning scheme have since been amended and this is version 8 of the instrument.' Council page: 'This LGIP amendment commenced on 11 September 2026, creating version 8 of the planning scheme.' Version 8 changed only the LGIP (Part 4). The dwelling house / zone siting provisions were last changed by the Better Housing Amendment (Major Amendment No. 3, Version 7, commenced 30 Oct 2024) and Administrative Amendment No. 3 (Version 7.1, 23 June 2025, format/numbering only). No replacement scheme is in force: the new City of Moreton Bay planning scheme is at early consultation (survey closed 12 July 2026; statutory consultation on a draft expected 2028). Pending amendments NOT in force: Major Amendment No. 4 (Morayfield South & bushfire, awaiting Minister), Major Amendment No. 5 (Narangba Innovation Precinct East, consultation 27 Jul - 24 Aug 2026). The ePlan front-end is a JavaScript SPA; text was retrieved from its public JSON API, which returns the HTML of each rule, for revision 96 (Version 8). URL pattern: https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/{sectionId}/0/false/11-Sep-2026/false (needs browser-like headers). Section ids: 226 = 9.3.1 Dwelling house code; 111 = 6.2.11 Rural residential zone code; 15 = Part 1; 46 = 5.7 Building work table; 100/99/98 = 5.5.6.1/5.5.6.2/5.5.6.3 GRZ precinct MCU tables; 77 = 5.5.11 Rural residential MCU table; 189 = 7.2.1.6 Redcliffe Kippa-Ring Interim residential precinct; 198 = 8.2.1 Coastal hazard overlay code. Definitions from the revision glossary endpoint https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1.$q$);
