SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$QDC relationship: 1.6 Editor's note (rule 278)$q$, 'APPLICATION', $q$specify alternative planning scheme provisions under section 33 of the Building Act 1975. This relates to alternative design solutions for boundary clearance and site cover provisions MP 1.1, 1.2 and 1.3 of the QDC.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/15/0/false/11-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$QDC relationship: 9.3.1 Table 9.3.1.1, note attached to RAD1-RAD6, RAD8-RAD14, RAD16-RAD25$q$, 'APPLICATION', $q$Note - Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role for a building development application under Division 2, Part 3, Schedule 9 of the Planning Regulation 2017.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$QDC relationship: 9.3.1 Table 9.3.1.1 RAD7 (same declaration form on RAD15 and RAD26)$q$, 'APPLICATION', $q$Note - For a Class 10 building or structure, Council has declared that a building or structure that is in a form that does not comply with this RAD, may: - have an extremely adverse effect on the amenity, or likely amenity, of the locality in which it is proposed to be established; or - be in extreme conflict with the character of the locality in which it is proposed to be established. Non-compliance with this RAD is an amenity and aesthetic impact matter for which Council will exercise a concurrence agency role for building work under Division 2, Part 3, Schedule 9 of the Planning Regulation 2017.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$QDC relationship: 5.7 Table 5.7.1 (rule 4424)$q$, 'APPLICATION', $q$Note - Concurrence agency issues are the matters identified as alternative provisions to the QDC or matters that relate to amenity and aesthetics in the requirements for accepted development contained in table 9.3.1.2. For these matters a concurrence agency response is required from Council as part of any building development application.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/46/0/false/11-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$QDC relationship: 6.2.11 concurrence agency issues table (rules 14707-14713; per the raw HTML all RAD codes sit in the 'Alternative provisions to the QDC' column)$q$, 'APPLICATION', $q$Concurrence agency issues for building work || Alternative provisions to the QDC || Matters that relate to amenity and aesthetics || RAD6 || Nil || RAD8 || RAD47 || RAD48 || RAD50$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/111/0/false/11-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$QDC relationship: 6.2.11 Table 6.2.11.1 RAD6$q$, 'APPLICATION', $q$Note - For building work associated with a dwelling house, this is an alternative provision to the QDC, part MP1.2, A3 and is a concurrence agency issue.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/111/0/false/11-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$QDC relationship: 6.2.11 Table 6.2.11.1 RAD48 (same note on E60)$q$, 'APPLICATION', $q$Note - For building work associated with a dwelling house, this is an alternative provision to the QDC, part MP1.2, A1 (a), (b) and (c), A2 (a), (b) and (d) and is a concurrence agency issue.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/111/0/false/11-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$QDC relationship: 9.3.1, editor's note after Table 9.3.1.5 (rule 30032)$q$, 'APPLICATION', $q$Editor's note - Side boundary setback standards in Table 9.3.1.5 include specific variations to the QDC for the applicable precincts that ensure the minimum side non-built to boundary wall setback on narrow lots is 1m to wall allowing space for eaves to project over the setback while also maintaining adequate separation between eaves and the side boundary (see figure below illustrating a typical outcome).$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def setback$q$, 'DEFINITION', $q$For a building or structure, the shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def outermost projection$q$, 'DEFINITION', $q$The outermost projection of any part of a building or structure including, in the case of a roof, the outside face of the fascia, or the roof structure where there is no fascia, or attached sunhoods or the like, but does not include retractable blinds, fixed screens, rainwater fittings, or ornamental attachments.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def site cover$q$, 'DEFINITION', $q$The proportion of the site covered by a building(s), structure(s) attached to the building(s) and carport(s), calculated to the outer most projections of the building(s) and expressed as a percentage. The term does not include: - any structure or part thereof included in a landscaped open space area such as a gazebo or shade structure; - basement car parking areas located wholly below ground level; and - eaves and sun shading devices.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def building height$q$, 'DEFINITION', $q$If specified: - in metres, the vertical distance between the ground level and the highest point of the building roof (apex) or parapet at any point, but not including load-bearing antenna, aerial, chimney, flagpole or the like; - in storeys, the number of storeys above ground level; or - in both metres and storeys, both (a) and (b) apply. Editor's note - Lift overruns, air conditioners and the like, are excluded from the measure of building height.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def ground level$q$, 'DEFINITION', $q$The level of the natural ground, or, where the level of the natural ground has been changed, the level as lawfully changed.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def storey$q$, 'DEFINITION', $q$A space that is situated between one floor level and the floor level next above, or if there is no floor above, the ceiling or roof above, but not a space that contains only: - a lift shaft, stairway or meter room - a bathroom, shower room, laundry, water closet, or other sanitary compartment - a combination of the above. A mezzanine is a storey. A roofed structure on or part of a rooftop that does not solely accommodate building plant and equipment is a storey. A basement is not a storey.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def domestic outbuilding$q$, 'DEFINITION', $q$A Class 10a building, as defined in the Building Code of Australia , that is ancillary to a residential use on the same premises and is limited to non-habitable buildings for the purpose of a shed, garage and carport. Editor's note - This term includes 'and the like' buildings or roofed structures. Editor's note - This term is a building or other roofed structure that is detached from the dwelling. It is solely a class 10a and does not incorporate a component of any other class. Further, Domestic outbuildings are not garages and carports constructed to appear as an integral part of a dwelling (e.g. a single roof over the dwelling and garage parts of a building) and where the roof of a carport is attached directly to a dwelling (i.e. not attached via an ancillary structure such as a roofed walkway or pergola etc.)$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def dwelling house$q$, 'DEFINITION', $q$Dwelling house means a residential use of premises involving - 1 dwelling and any domestic outbuildings associated with the dwelling; or - 2 dwellings, 1 of which is a secondary dwelling, and any domestic outbuildings associated with either dwelling.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.1 Use definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def frontage$q$, 'DEFINITION', $q$* Any boundary line, or part thereof, of a lot which abuts a road reserve.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def primary frontage$q$, 'DEFINITION', $q$* Means: - for a lot with only one frontage to a road, the frontage to that road; or - for a lot with more than one frontage to a road (including a corner lot); - if the lot has a frontage to a laneway as described in Planning Scheme Policy Neighbourhood Design, the non-laneway frontage; and - if the frontages are to roads of a different order (as shown on the Overlap Map - Road Hierarchy) and excluding a motorway, the highest order road; and - if the frontages are to roads of the same order (as shown on the Overlap Map - Road Hierarchy): - the road that existing development on the land proposed to remain has, or is required to have, its principal pedestrian entrance into the development from (generally in the form of a front door); or - where (A.) does not apply; the road that development on adjoining land (having the same multiple road frontages) has or is required to have its principal pedestrian entrance into the development from (generally in the form of a front door); or - where (A.) and (B.) do not apply, the frontage the development is required to have or will have its principal pedestrian entrance into the development from (generally in the form of a front door). ...$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def secondary frontage$q$, 'DEFINITION', $q$* A frontage that is not the primary frontage.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def main building line$q$, 'DEFINITION', $q$* The line extending from the longest wall excluding a garage, carport or other domestic outbuilding in the front elevation of the building. Note - Excludes porticos, etc Figure - Main building line$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def built to boundary wall$q$, 'DEFINITION', $q$* A wall of a Dwelling house (class 1a) setback 200mm or less from a boundary.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def roofed area$q$, 'DEFINITION', $q$* The area of the roof of each building or other structure as projected onto a horizontal plane.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def trafficable water body$q$, 'DEFINITION', $q$* A body of water, whether natural, constructed or artificially improved, which is ordinarily of sufficient size and depth to allow use by any occupied, motorised vessel. The term includes a canal, lake, river or stream, regardless of its salinity level and whether or not it is subject to tidal influence. However, the term specifically excludes any dam which is fully contained within a single lot, wastewater ponds, tailings dams and any other body of water to which entry by the public for motorised boating purposes is not permitted.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def developed lot$q$, 'DEFINITION', $q$* A lot that is provided with infrastructure and services (including reticulated water and sewer, stormwater, dedicated roads and electricity) of a standard and capacity required for the proposed development.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def plan of development$q$, 'DEFINITION', $q$* A plan approved by Council (generally as part of a reconfiguring a lot application) that regulates building elements (e.g. Built to boundary walls, driveway location etc) for development on narrow lots (generally lots with a frontage of 12.5m or less).$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def gross floor area$q$, 'DEFINITION', $q$The total floor area of all storeys of a building (measured from the outside of the external walls or the centre of a common wall), other than areas used for the following: - building services, plant and equipment; - access between levels; - ground floor public lobby; - a mall; - the parking, loading and manoeuvring of motor vehicles; - unenclosed private balconies whether roofed or not.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/rev/96/11-Sep-2026/1$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$def wall height / mean height$q$, 'DEFINITION', $q$NOT DEFINED in the scheme glossary (no 'wall height' or 'mean height' entry among the 386 glossary terms). The Dwelling house code states: "Editor's note - The calculation for mean height is defined in the QDC." Setback tables use 'Height of wall' without a definition.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1 (absence) / 9.3.1 RAD26 editor's note$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$LOA 5.7 Table 5.7.1 Building work (rule 4424) Building work, not associated with a material change of use, for a Dwelling house (incl. domestic outbuildings) / General residential zone (all precincts)$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work, not associated with a material change of use, for a Dwelling house in the General residential zone or the Emerging community zone, Transition precinct on a developed lot || Accepted development || If complying with the circumstances for accepted development in Table 1.7.7.1 'Accepted development'. Editor's note - Development approval is not required || Accepted development subject to requirements || If not complying with the circumstances for accepted development and: - complying with the relevant requirements for accepted development; or - complying with the relevant criteria for accepted development subject to requirements other than those identified as concurrence agency issues in the Dwelling house code. ... 9.3.1 'Dwelling house code' || Assessable development - Code assessment || If not otherwise specified. Note - For example if not complying with the relevant value and constraint requirements for accepted development or not complying with the circumstances for accepted development. Note - This is a limited assessment to which section 5.3.3.1.a.ii. applies.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/46/0/false/11-Sep-2026/false$q$, $q$Level: Accepted development / Accepted development subject to requirements / Code assessment (limited). Conditions: Accepted (no approval) if within the Table 1.7.7.1 circumstances (e.g. not in the Heritage and landscape character overlay or Erosion Prone Area, increase in GFA/roofed area not more than 50 m2 in GRZ, and complies with setback, site cover, height and roofed area requirements). Otherwise ADSR against 9.3.1 Dwelling house code; non-compliance with concurrence-agency RADs -> Council concurrence agency on the building application; non-compliance with values/constraints RADs -> code assessment.$q$, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$LOA 5.7 Table 5.7.1 (rule 4425) Building work, not associated with a material change of use, for a Dwelling house / Rural residential zone; Rural zone; Township zone - Township residential precinct$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work, not associated with a material change of use, for a Dwelling house; in the following zones: - Township zone - Township residential precinct - Rural zone - Rural residential zone. || Accepted development || If complying with the circumstances for accepted development in Table 1.7.7.1 'Accepted development'. ... Accepted development subject to requirements || If not complying with the circumstances for accepted development and: ... Note - Concurrence agency issues are the matters identified in the relevant zone code as either alternative provisions to the QDC or matters that relate to amenity and aesthetics. For these matters a concurrence agency response is required from Council as part of any building development application. || Relevant zone code (relevant precinct only) ... Assessable development - Code assessment || If not otherwise specified. Note - This is a limited assessment to which section 5.3.3.1.a.ii. applies.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/46/0/false/11-Sep-2026/false$q$, $q$Level: Accepted / Accepted development subject to requirements / Code assessment (limited). Conditions: As above but the assessment benchmark is the relevant zone code (6.2.11 for Rural residential). Concurrence agency issues = RADs identified in the zone code as alternative provisions to QDC or amenity/aesthetic matters.$q$, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$LOA 1.7.7 Table 1.7.7.1 Accepted development (rule 1943) Accepted development circumstances for building work (Table 1.7.7.1) / All zones except those listed$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work, not associated with a material change of use || If: - not in the following zones, precincts or overlay maps: - Limited development zone; or - Environmental management and conservation zone; or - Township zone - Township centre precinct; or - Township zone - Township convenience precinct; or - Coastal planning area on Overlay map - Coastal hazard (Erosion Prone Area); or - Overlay map - Heritage and landscape character; and - not associated with a secondary dwelling; and - results in no net reduction in the minimum quantity and standard of landscaping, private or communal open space or car parking spaces required under the planning scheme or under an existing Development Permit for the use; and - complies with setback, site cover, building height and roofed area requirements for the applicable zone, precinct or development code; and - results in: - an increase in gross floor area or roofed area of not more than: - 50m2 in the General residential zone, Rural residential zone, Emerging community zone, Rural zone or Township zone - Township residential precinct; or - 80m2 in any other zone and precinct. OR - raising an existing dwelling house up to the maximum height allowed by the requirements for accepted developments and examples that achieve aspects of the performance outcomes for the relevant zone or precinct. Includes any previous increases in gross floor area and roofed area undertaken as accepted development or accepted development subject to requirements under the MBRC Planning Scheme.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/15/0/false/11-Sep-2026/false$q$, $q$Level: Accepted development (no approval, no requirements). Conditions: Not in Limited development zone, EM&C zone, Township centre/convenience precincts, Coastal planning area on the Erosion Prone Area overlay, or Heritage and landscape character overlay; not associated with a secondary dwelling; no net reduction in landscaping/open space/parking; complies with setback, site cover, height and roofed area requirements; increase in GFA or roofed area not more than 50 m2 in GRZ, Rural residential, Emerging community, Rural or Township residential (80 m2 elsewhere), cumulative.$q$, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$LOA 5.5.6.2 Suburban neighbourhood precinct MCU table Material change of use - Dwelling house / General residential zone - Suburban neighbourhood precinct (same form in Coastal communities and Next ge$q$, 'LEVEL_OF_ASSESSMENT', $q$Dwelling house || Accepted development subject to requirements || If complying with the relevant requirements for accepted development. Note - If it does not meet requirements for accepted development that are alternative provisions to the QDC, matters that relate to amenity and aesthetics or matters identified in Schedule 9, Part 3, Division 2, Table 1 of the Regulation,as stated in the requirements for accepted development contained in Table 9.3.1.2 a concurrence agency response is required from Council. || 9.3.1 'Dwelling house code' || Assessable development - Code assessment || If it does not meet the relevant value and constraint requirements for accepted development subject to requirements. Note - This is a limited assessment to which section 5.3.3.1.a.ii. applies.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/99/0/false/11-Sep-2026/false$q$, $q$Level: Accepted development subject to requirements; Code assessment if values/constraints RADs not met. Conditions: Assessment benchmark 9.3.1 Dwelling house code. Non-compliance with RADs that are alternative provisions to QDC / amenity and aesthetics -> concurrence agency response, not code assessment.$q$, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$LOA 5.5.11 Rural residential zone MCU table Material change of use - Dwelling house / Rural residential zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Dwelling house || Editor's note - A Dwelling house in the Rural residential zone is not subject to the Dwelling house code. || Accepted development || If for a temporary use and complying with the circumstances for accepted development in Table 1.7.7.1 'Accepted development'. ... Accepted development subject to requirements || If not otherwise specified. || 6.2.11 'Rural residential zone code'$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/77/0/false/11-Sep-2026/false$q$, $q$Level: Accepted development subject to requirements (accepted if temporary use). Conditions: Assessed against 6.2.11 Rural residential zone code; the Dwelling house code does NOT apply.$q$, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$LOA 5.10.2 Flood hazard overlay table Building work, not associated with a material change of use (incl. dwelling house) / Any zone within Flood hazard overlay High risk area / Medium risk area / Drai$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work not associated with a material change of use. || No change || If in the Balance flood planning area ... Assessable development - Code assessment || If in the following: - High risk area not included in the Limited development zone; or - Medium risk area; or - Drainage investigation area identified on Figure 8.2.2.1 to 8.2.2.10 of the Flood hazard overlay code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/53/0/false/11-Sep-2026/false$q$, $q$Level: Code assessment (Flood hazard overlay code). Conditions: Balance flood planning area: no change.$q$, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$LOA 5.10.1 Coastal hazard overlay table (rule 5588) Building work, not associated with a material change of use / Coastal hazard overlay areas$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work not associated with a material change of use || No change || If: - in the Balance coastal planning area; or - in the Erosion Prone Area and not increasing gross floor area by more than 50m2. ... Assessable development - Code assessment || If: - in the Erosion Prone Area and increasing gross floor area by more than 50m2; or - in the following: - High risk storm tide inundation area not included in the Limited development zone; or - Medium risk storm tide inundation area.$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/54/0/false/11-Sep-2026/false$q$, $q$Level: Code assessment (Coastal hazard overlay code) in listed areas. Conditions: Erosion Prone Area with GFA increase > 50 m2, High risk storm tide inundation area (not Limited development zone) or Medium risk storm tide inundation area.$q$, NULL);
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$LOA 5.9.1.9 Building work (Redcliffe Kippa-Ring local plan) Building work, not associated with a material change of use, for a Dwelling house / Redcliffe Kippa-Ring local plan - Interim residential pr$q$, 'LEVEL_OF_ASSESSMENT', $q$Building work, not associated with a material change of use, for a Dwelling house in the Interim residential precinct || Accepted development || If complying with the circumstances for accepted development in Table 1.7.7.1 'Accepted development'. ... Accepted development subject to requirements || If: - complying with the relevant requirements for accepted development; and - not complying with the circumstances for accepted development. Note - If it does not meet criteria that are alternative provisions to the QDC or matters that relate to amenity and aesthetics as stated in the assessment criteria contained in table 9.3.1.2. A concurrence agency response is required from Council. || 9.3.1 'Dwelling house code' 7.2.1 'Redcliffe Kippa-Ring local plan code' (applicable precinct)$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/67/0/false/11-Sep-2026/false$q$, $q$Level: Accepted / ADSR / Code assessment (limited). Conditions: Benchmarks are BOTH 9.3.1 Dwelling house code and 7.2.1 Redcliffe Kippa-Ring local plan code (applicable precinct).$q$, NULL);
