SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$overlay Riparian and wetland setbacks 9.3.1 RAD54$q$, 'OTHER', $q$No development is to occur within: - 50m from top of bank for W1 waterway and drainage line - 30m from top of bank for W2 waterway and drainage line - 20m from top of bank for W3 waterway and drainage line - 100m from the edge of a Ramsar wetland, 50m from all other wetlands.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$9.3.1 Dwelling house code (values and constraints)$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$No development within 20-50 m of mapped waterway top of bank or 50/100 m of wetlands.$q$, NULL);
