SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.1 RAD1 (Part B: PO1/E1)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD1 Building height does not exceed that mapped on Overlay map – Building heights. Note - Minimum's mapped on Overlay map - Building heights, do not apply to Dwelling houses. Note - The above does not apply to domestic outbuildings. Refer to requirements for Domestic outbuildings in this code. Note - Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role for a building development application under Division 2, Part 3, Schedule 9 of the Planning Regulation 2017.$q$, 'VERIFIED_VERBATIM', $q$rule 19681$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$Building height = vertical distance between ground level and the highest point of the roof (apex) or parapet.$q$, $q$mb_dh_rad1_building_height_overlay$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_rad1_building_height_overlay", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "HEIGHT.BUILDING", "title": "Table 9.3.1.1 RAD1 (Part B: PO1/E1)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "RAD1 Building height does not exceed that mapped on Overlay map – Building heights. Note - Minimum's mapped on Overlay map - Building heights, do not apply to Dwelling houses. Note - The above does not apply to domestic outbuildings. Refer to requirements for Domestic outbuildings in this code. Note - Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role for a building development application under Division 2, Part 3, Schedule 9 of the Planning Regulation 2017.", "extracted_value": null, "extracted_operator": "<="}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/COASTAL_COMMUNITIES"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/SUBURBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/URBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT_MORAYFIELD_SOUTH"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_rad1_building_height_overlay", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_building_height\", \"operator\": \"<=\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"value is the maximum mapped on Overlay map - Building heights for the lot\"], \"exceptions\": [\"mapped minimums do not apply to dwelling houses\", \"domestic outbuildings use RAD26\"], \"formula_text\": null}\nStructure scope 'Dwelling house (not domestic outbuildings)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33).\nResearcher notes: Numeric value is map-based (see rule mb_building_heights_overlay_categories). Most low-density residential land is mapped 'Max 8.5m' per council open data, but the lot-specific value must be read from the map."}$q$::jsonb);
