SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.1 RAD3 (Part B E3.1)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD3 Setbacks (excluding built to boundary walls) comply with: - Emerging community zone: - Transition precinct (developed lot) Morayfield South urban area identified in 'Figure 9.3.1.1 Morayfield South - Urban area' - Table 9.3.1.5 'Setbacks' - Transition precinct (developed lot) all other areas - Table 9.3.1.5 'Setbacks' - General residential zone: - Coastal communities precinct - Table 9.3.1.3 'Setbacks' - Suburban neighbourhood precinct - Table 9.3.1.4 'Setbacks' - Next generation neighbourhood precinct - Table 9.3.1.5 'Setbacks' - Urban neighbourhood precinct - Table 9.3.1.6 - Caboolture West local plan: - Urban living precinct - Next generation sub-precinct - Table 9.3.1.5 'Setbacks' - Redcliffe Kippa-Ring local plan: - Interim residential precinct - Table 9.3.1.3 'Setbacks' Except for carports in the primary and secondary frontage where they: - are setback a minimum of: - 5.4m; or - if the dwelling was built before 2005: - not less than the setback to an existing lawfully constructed carport or garage on an adjoining lot having the same road frontage (where a lawfully constructed carport or garage is located on both sides, the lesser of the two is applicable); or - 0.5m, whichever is the greater; and - remain open and are not enclosed by walls, screens, doors or the like. Note - Non-compliance with this RAD is a planning scheme matter ... Editor's Note - Greater setbacks may be required if the lot adjoins an environmental corridor or area (refer to values and constraints for details). Note - The above setbacks apply only to Class 1a and Class 10a buildings/structures, with the exception of domestic outbuildings (e.g garden shed) where in the Caboolture West local plan - Urban living precinct - Next generation sub-precinct and with a maximum roofed area not more than 10m2 and a height of not more than 2.5m.$q$, 'VERIFIED_VERBATIM', $q$rule 19684$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot'. The tables split columns 'To wall' vs 'To OMP' (outermost projection) and 'To covered car parking space and domestic outbuildings'. Row selection is by 'Height of wall' (not defined in the scheme).$q$, $q$mb_dh_rad3_setback_table_routing_and_carport$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_rad3_setback_table_routing_and_carport", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "GARAGE.FRONTAGE", "title": "Table 9.3.1.1 RAD3 (Part B E3.1)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": {"op": "unencoded", "text": "pre-2005 dwelling: max(min(adjoining lawful carport/garage setbacks), 0.5 m); else 5.4 m", "extracted_value": 5.4, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/COASTAL_COMMUNITIES"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/SUBURBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/URBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT_MORAYFIELD_SOUTH"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_rad3_setback_table_routing_and_carport", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"carport_min_road_setback\", \"operator\": \"conditional\", \"value\": 5.4, \"unit\": \"m\", \"conditions\": [\"carport must remain open (not enclosed by walls, screens, doors)\", \"applies to primary and secondary frontage\"], \"exceptions\": [\"dwelling built before 2005: not less than setback of lawful carport/garage on adjoining lot with same frontage (lesser if both sides) or 0.5 m, whichever is greater\", \"setback tables apply only to Class 1a and Class 10a\", \"Caboolture West Next generation sub-precinct: sheds <= 10 m2 roofed area and <= 2.5 m high exempt from the setback tables\"], \"formula_text\": \"pre-2005 dwelling: max(min(adjoining lawful carport/garage setbacks), 0.5 m); else 5.4 m\"}\nStructure scope 'Class 1a and Class 10a buildings/structures; carports in primary/secondary frontage' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33).\nResearcher notes: E3.1 in Part B for Redcliffe Interim residential reads 'Interim residential precinct - Setbacks' (table number omitted) and E3.1 routes Morayfield South to Table 9.3.1.6 whereas RAD3 routes it to Table 9.3.1.5 - internal inconsistency; Table 9.3.1.6's heading names Morayfield South."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_dh_rad3_setback_table_routing_and_carport@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.3 Setbacks (via RAD3/E3.1)$q$, 'TABLE', $q$Table 9.3.1.3 Setbacks - Coastal communities precinct and Redcliffe Kippa-Ring local plan - Interim residential precinct. Columns: Height of wall || Frontage Primary [To wall | To OMP | To covered car parking space and domestic outbuildings] || Frontage Secondary to street [To wall | To OMP | To covered car parking space and domestic outbuildings] || Frontage Secondary to lane || Side || Rear || Trafficable water body. Rows: Less than 4.5m || Min 6m || Min 4.5m || Min 5.4 || Min 3m || Min 2m || Min 5.4 || Min 0.5 || Refer to standard as in QDC || Refer to standard as in QDC || Min 4.5m ; 4.5m to 8.5m || Min 6m || Min 4.5m || N/A || Min 3m || Min 2m || N/A || Min 0.5 || Refer to standard as in QDC || Refer to standard as in QDC || Min 4.5m ; Greater than 8.5m || Min 6m || Min 4.5m || N/A || Min 3m || Min 2m || N/A || Min 0.5 || Refer to Standard as in QDC || Refer to standard as in QDC || Min 4.5m$q$, 'VERIFIED_VERBATIM', $q$rules 32377, 30074, 30015-30017$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot'. The tables split columns 'To wall' vs 'To OMP' (outermost projection) and 'To covered car parking space and domestic outbuildings'. Row selection is by 'Height of wall' (not defined in the scheme).$q$, $q$mb_dh_t93113_coastal_front$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_t93113_coastal_front", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.FRONTAGE", "title": "Table 9.3.1.3 Setbacks (via RAD3/E3.1)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "select row by height of wall; apply both 'to wall' and 'to OMP' minimums", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/COASTAL_COMMUNITIES"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_t93113_coastal_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_primary_frontage_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"wall height < 4.5 m: to wall Min 6m, to OMP Min 4.5m, to covered car parking space/domestic outbuildings Min 5.4\", \"wall height 4.5-8.5 m: to wall Min 6m, to OMP Min 4.5m, car/outbuildings N/A\", \"wall height > 8.5 m: to wall Min 6m, to OMP Min 4.5m, car/outbuildings N/A\"], \"exceptions\": [\"carports: RAD3 exception (5.4 m / pre-2005 rule) applies\"], \"formula_text\": \"select row by height of wall; apply both 'to wall' and 'to OMP' minimums\"}\nStructure scope 'Class 1a dwelling house and Class 10a (covered car parking spaces, domestic outbuildings)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33)."}$q$::jsonb);
