SELECT define_rule($q${"rule_id": "CMB.mb_dh_t93114_suburban_waterbody", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OTHER", "title": "Table 9.3.1.4 Setbacks (via RAD3/E3.1)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_OTHER", "operator": ">=", "value": 4.5, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/SUBURBAN_NEIGHBOURHOOD"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_t93114_suburban_waterbody", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_trafficable_water_body_setback\", \"operator\": \">=\", \"value\": 4.5, \"unit\": \"m\", \"conditions\": [\"applies to OMP, wall and covered car parking/domestic outbuildings, all wall heights\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Class 1a and Class 10a incl. covered car parking and domestic outbuildings' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33).\nResearcher notes: Table heading also names 'Township zone - Residential precinct', but Table 5.7.1 sends Township residential dwelling houses to the Township zone code, not 9.3.1."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_dh_t93114_suburban_waterbody@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.5 Setbacks (via RAD3/E3.1)$q$, 'TABLE', $q$Table 9.3.1.5 Setbacks - Emerging community zone - Transition precinct (developed lot), General residential zone - Next generation neighbourhood precinct and Caboolture West local plan - Urban living precinct - Next generation sub-precinct. Table 9.3.1.5 has an extra column 'Side Non-built to boundary wall and Rear To OMP' = 'As per applicable side or rear boundary standard to wall minus 0.5m' (all rows). *Note - The minimum setback to covered car parking spaces may be reduced to 4.5m where: - the primary or secondary frontage of the lot adjoins a road reserve with a minimum rear verge width of 1m or greater and includes a footpath with a width of 2m or greater; - The lot has a primary frontage greater than 7.5m and no greater than 10m (Lot type B).. Columns: Height of wall || Frontage Primary [To wall | To OMP | To covered car parking space and domestic outbuildings] || Frontage Secondary to street [To wall | To OMP | To covered car parking space and domestic outbuildings] || Frontage Secondary to lane || Side || Rear || Trafficable water body. Rows: Less than 4.5m || Min 3m || Min 2m || Min 5.4m* || Min 2m || Min 1m || Min 5.4m* || Min 0.5 || For lots with a primary frontage ≤12m, Min 1m OR For lots with a primary frontage >12m, refer to standard as in QDC but measured to wall || Min 5m OR Where the longest side boundary is ≤25m or where the primary frontage is ≤9.5m - Min 3m OR Where the primary frontage is ≤9.5m and the lot is adjoining a park or directly opposite a park fronting the same street - refer to standard as in QDC but measured to wall || Min 4.5m ; 4.5m to 8.5m || Min 3m || Min 2m || N/A || Min 2m || Min 1m || N/A || Min 0.5 || Refer to standard as in QDC but measured to wall || Min 5m OR Where the longest side boundary is ≤25m or where the primary frontage is ≤9.5m - Min 3m OR Where the primary frontage is ≤9.5m and the lot is adjoining a park or directly opposite a park fronting the same street - refer to standard as in QDC but measured to wall || Min 4.5m ; Greater than 8.5m || Min 6m || Min 5m || N/A || Min 3m || Min 2m || N/A || Min 0.5 || Refer to standard as in QDC but measured to wall || Min 5m OR Where the longest side boundary is ≤25m or where the primary frontage is ≤9.5m - Min 3m OR Where the primary frontage is ≤9.5m and the lot is adjoining a park or directly opposite a park fronting the same street - refer to standard as in QDC but measured to wall || Min 4.5m$q$, 'VERIFIED_VERBATIM', $q$rules 32379, 30076, 30027-30030$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot'. The tables split columns 'To wall' vs 'To OMP' (outermost projection) and 'To covered car parking space and domestic outbuildings'. Row selection is by 'Height of wall' (not defined in the scheme).$q$, $q$mb_dh_t93115_nextgen_front$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_t93115_nextgen_front", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "SETBACK.FRONTAGE", "title": "Table 9.3.1.5 Setbacks (via RAD3/E3.1)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "TABLE", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "select row by height of wall; apply both 'to wall' and 'to OMP' minimums", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_t93115_nextgen_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"min_primary_frontage_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"wall height < 4.5 m: to wall Min 3m, to OMP Min 2m, to covered car parking space/domestic outbuildings Min 5.4m*\", \"wall height 4.5-8.5 m: to wall Min 3m, to OMP Min 2m, car/outbuildings N/A\", \"wall height > 8.5 m: to wall Min 6m, to OMP Min 5m, car/outbuildings N/A\"], \"exceptions\": [\"carports: RAD3 exception (5.4 m / pre-2005 rule) applies\", \"covered car parking setback may reduce to 4.5 m where verge/footpath conditions met and primary frontage > 7.5 m and <= 10 m\"], \"formula_text\": \"select row by height of wall; apply both 'to wall' and 'to OMP' minimums\"}\nStructure scope 'Class 1a dwelling house and Class 10a (covered car parking spaces, domestic outbuildings)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33)."}$q$::jsonb);
