INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CMB.mb_dh_t93119_site_cover_urban@2026-09-11$q$, $q$QDC11.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.1 RAD7 (PO7/E7)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD7 Garage and carport openings, where located within 20m of the site frontage, are in accordance with the table below: Primary or Secondary frontage || Covered car space opening(s) per street frontage ; Greater than 18m || Not specified ; 12.5m to 18m || 6m wide maximum ; Less than 12.5m* || Single storey dwelling: - maximum 50% of the frontage width (being the frontage vehicle access is from); - recessed: - at least 1.0m behind the main building line;or - at least 1.0m behind a front portico and no more than 2.0m in front of the main building line. Two storey dwelling: - 6.0m wide maximum; - recessed 1.0m behind the front wall or balcony of upper level. Editor's note - Front wall is to have a minimum length of 40% of the adjoining frontage. OR For a laneway lot (Single or two storey): no maximum. Note - *For a laneway lot, vehicle access and parking must be provided via the laneway. ... Note - Where not associated with a Class 10 building or structure, non-compliance with this RAD is a planning scheme matter ... Note - For a Class 10 building or structure, Council has declared that a building or structure that is in a form that does not comply with this RAD, may: ... Non-compliance with this RAD is an amenity and aesthetic impact matter ...$q$, 'VERIFIED_VERBATIM', $q$rule 19690$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$Main building line = line extending from the longest wall excluding garage, carport or other domestic outbuilding in the front elevation (excludes porticos).$q$, $q$mb_dh_rad7_garage_openings$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_rad7_garage_openings", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "GARAGE.FRONTAGE", "title": "Table 9.3.1.1 RAD7 (PO7/E7)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": {"op": "unencoded", "text": "RAD7 Garage and carport openings, where located within 20m of the site frontage, are in accordance with the table below: Primary or Secondary frontage || Covered car space opening(s) per street frontage ; Greater than 18m || Not specified ; 12.5m to 18m || 6m wide maximum ; Less than 12.5m* || Single storey dwelling: - maximum 50% of the frontage width (being the frontage vehicle access is from); - recessed: - at least 1.0m behind the main building line;or - at least 1.0m behind a front portico and no more than 2.0m in front of the main building line. Two storey dwelling: - 6.0m wide maximum; - recessed 1.0m behind the front wall or balcony of upper level. Editor's note - Front wall is to have a minimum length of 40% of the adjoining frontage. OR For a laneway lot (Single or two storey): no maximum. Note - *For a laneway lot, vehicle access and parking must be provided via the laneway. ... Note - Where not associated with a Class 10 building or structure, non-compliance with this RAD is a planning scheme matter ... Note - For a Class 10 building or structure, Council has declared that a building or structure that is in a form that does not comply with this RAD, may: ... Non-compliance with this RAD is an amenity and aesthetic impact matter ...", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m|%", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/COASTAL_COMMUNITIES"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/SUBURBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/URBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT_MORAYFIELD_SOUTH"}], "subjects": ["CLASS_10A"], "sources": [{"key": "mb_dh_rad7_garage_openings", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_garage_opening_width\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m|%\", \"conditions\": [\"frontage > 18 m: not specified\", \"frontage 12.5-18 m: 6 m max\", \"frontage < 12.5 m single storey: <= 50% frontage width and recessed >= 1.0 m behind main building line (or >= 1.0 m behind portico and <= 2.0 m in front of MBL)\", \"frontage < 12.5 m two storey: 6.0 m max, recessed 1.0 m behind upper level front wall/balcony\", \"laneway lot: no maximum\"], \"exceptions\": [\"only openings within 20 m of the site frontage\"], \"formula_text\": null}\nStructure scope 'Garage and carport openings within 20 m of the site frontage' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: YES for non-Class 10 work ('planning scheme matter'); for a Class 10 building it is an amenity and aesthetic concurrence matter, not an alternative provision."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_dh_rad7_garage_openings@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.1 RAD8 (E8.x)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD8 Any new crossovers and driveways or changes to existing crossovers and driveways: - if there is an approved plan of development, are located in accordance with the plan of development approved by council as part of a development approval or as otherwise amended by council in writing; or - if no approved plan of development applies to the land, are a maximum 40% of the frontage from which access is being obtained or 5m, whichever is lesser, in accordance with Planning scheme policy - Integrated design (Appendix A).$q$, 'VERIFIED_VERBATIM', $q$rule 19692$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_dh_rad8_driveway_width$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_rad8_driveway_width", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "GARAGE.FRONTAGE", "title": "Table 9.3.1.1 RAD8 (E8.x)", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": "<=", "value": {"op": "unencoded", "text": "min(0.4 * frontage, 5 m)", "extracted_value": null, "extracted_operator": "<="}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/COASTAL_COMMUNITIES"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/SUBURBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/URBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT_MORAYFIELD_SOUTH"}], "subjects": ["ANY"], "sources": [{"key": "mb_dh_rad8_driveway_width", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_driveway_width\", \"operator\": \"<=\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"no POD: lesser of 40% of frontage or 5 m\"], \"exceptions\": [\"approved POD governs\"], \"formula_text\": \"min(0.4 * frontage, 5 m)\"}\nStructure scope 'Crossovers and driveways' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: YES - RAD carries note 'Non-compliance with this RAD is a planning scheme matter for which Council will exercise a concurrence agency role ...'; Table 1.6.1 identifies 9.3.1 'RADs and performance outcomes identified by notes as a planning scheme matter' as the alternative provisions to QDC boundary clearance and site cover provisions (Building Act s33)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_dh_rad8_driveway_width@2026-09-11$q$;
SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.1 RAD26(a) (PO22/E22)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD26 Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: Size of lot || Maximum roofed area ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; >1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 - have a maximum and mean building height as follows: - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within the primary frontage, secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports specified in this code. Note - for c. above to determine the main building line a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Council has declared that a building or structure that is in a form that does not comply with this RAD, may: ... Non-compliance with this RAD is an amenity and aesthetic impact matter for which Council will exercise a concurrence agency role for building work under Division 2, Part 3, Schedule 9 of the Planning Regulation 2017. Editor's note - The calculation for mean height is defined in the QDC.$q$, 'VERIFIED_VERBATIM', $q$rule 19717$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$Roofed area = area of the roof projected onto a horizontal plane; combined across all domestic outbuildings. Attached garages/carports under the dwelling roof are not 'domestic outbuildings'.$q$, $q$mb_dh_rad26_outbuilding_roofed_area$q$);
SELECT define_rule($q${"rule_id": "CMB.mb_dh_rad26_outbuilding_roofed_area", "instrument_version": "MBRC_PLANNING_SCHEME_2016@2026-09-11", "topic": "OUTBUILDING.SIZE", "title": "Table 9.3.1.1 RAD26(a) (PO22/E22)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OUTBUILDING_SIZE", "operator": "<=", "value": {"op": "unencoded", "text": "RAD26 Domestic outbuildings: - have a total combined maximum roofed area as outlined in the table below: Size of lot || Maximum roofed area ; Less than 600m2 || 50m2 ; 600m2 - 1000m2 || 70m2 ; >1000m2 – 2000m2 || 80m2 ; Greater than 2000m2 || 150m2 - have a maximum and mean building height as follows: - where in front of the main building line for a carport - have a maximum building height of 3.3m and a mean height not exceeding 2.7m; or - for all other instances - have a maximum building height of 4m and a mean height not exceeding 3.5m; - are located behind the main building line and not within the primary frontage, secondary frontage or trafficable water body setbacks except where for a carport and complying with the front setback for carports specified in this code. Note - for c. above to determine the main building line a trafficable water body boundary is to be treated the same as a secondary frontage. Note - Council has declared that a building or structure that is in a form that does not comply with this RAD, may: ... Non-compliance with this RAD is an amenity and aesthetic impact matter for which Council will exercise a concurrence agency role for building work under Division 2, Part 3, Schedule 9 of the Planning Regulation 2017. Editor's note - The calculation for mean height is defined in the QDC.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m2", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-11", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "MORETON_BAY"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/COASTAL_COMMUNITIES"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:REDCLIFFE_KIPPA_RING/INTERIM_RESIDENTIAL"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/SUBURBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/NEXT_GENERATION_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT"}, {"level": "LOCAL_PLAN_PRECINCT", "local_plan_precinct": "CMB:CABOOLTURE_WEST/URBAN_LIVING_NEXT_GENERATION"}, {"level": "PRECINCT", "precinct": "CMB:GENERAL_RESIDENTIAL/URBAN_NEIGHBOURHOOD"}, {"level": "PRECINCT", "precinct": "CMB:EMERGING_COMMUNITY/TRANSITION_DEVELOPED_LOT_MORAYFIELD_SOUTH"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "mb_dh_rad26_outbuilding_roofed_area", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"max_total_outbuilding_roofed_area\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m2\", \"conditions\": [\"lot < 600 m2: 50 m2\", \"600-1000 m2: 70 m2\", \"> 1000-2000 m2: 80 m2\", \"> 2000 m2: 150 m2\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'Domestic outbuildings (detached Class 10a shed, garage, carport) - total combined' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: NO - not an alternative provision; the RAD is declared an 'amenity and aesthetic impact matter' (Planning Regulation sch 9 pt 3 div 2) for which Council is concurrence agency."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CMB.mb_dh_rad26_outbuilding_roofed_area@2026-09-11$q$;
