SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 9.3.1.2 PO3$q$, 'PERFORMANCE_OUTCOME', $q$PO3 Dwelling houses and structures are setback to; - be consistent with the intended character of the streetscape, precinct and zone; ... - ensure covered car parking spaces and domestic outbuildings that are visible from the street or public place are of a scale, location and built form that is consistent with the existing streetscape and character of the precinct and avoids dominating or otherwise negatively impacting the streetscape or adjoining properties. ... Note - This performance outcome is a planning scheme matter against which Council must undertake its concurrence agency assessment under Division 2, Part 3, Schedule 9 of the Planning Regulation 2017 for non-compliance with the corresponding RAD(s) ... Editor's note - The boundary to a laneway is not a rear boundary and is always treated as a frontage.$q$, 'VERIFIED_VERBATIM', $q$rule 29911$q$, NULL, $q$9.3.1 Dwelling house code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/226/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_dh_po3_setbacks_performance$q$);
