SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.11.1 RAD3 (E4)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD3 Unless otherwise specified elsewhere in this code, the minimum setbacks from a property boundary are as follows: - road boundary – 6m - side boundary – 4.5m - rear boundary – 4.5m. Note - This provision does not apply where a development footprint exists for a lot. Note - This provision does not apply to swimming pools. For swimming pools, refer to Queensland Development Codes, Acceptable Solutions. Note - Where located in a bushfire hazard area (see Overlay map - Bushfire hazard) a greater setback may be required. See values and constraints requirements Bushfire hazard.$q$, 'VERIFIED_VERBATIM', $q$rule 14725$q$, NULL, $q$6.2.11 Rural residential zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/111/0/false/11-Sep-2026/false$q$, $q$$q$, $q$mb_rr_rad3_setbacks_general$q$);
