SELECT define_provision($q$MBRC_PLANNING_SCHEME_2016@2026-09-11$q$, $q$Table 6.2.11.1 RAD48 (E60)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RAD48 Setbacks (including domestic outbuildings) comply with the following: - Road boundary - 6m - Side and rear boundary: Height of wall || Minimum setback from side or rear boundary ; 3m or less || 1.5m ; Greater than 3m to 4.5m || 2m ; Greater than 4.5m || 4m. Note - For building work associated with a dwelling house, this is an alternative provision to the QDC, part MP1.2, A1 (a), (b) and (c), A2 (a), (b) and (d) and is a concurrence agency issue. Note - This provision does not apply where a development footprint exists for a lot.$q$, 'VERIFIED_VERBATIM', $q$rule 14786$q$, NULL, $q$6.2.11 Rural residential zone code$q$, NULL, $q$https://eplan.moretonbay.qld.gov.au/planningscheme/api/l/r/111/0/false/11-Sep-2026/false$q$, $q$Setback = 'shortest distance measured horizontally from the outer most projection of a building or structure to the vertical projection of the boundary of the lot'. The tables split columns 'To wall' vs 'To OMP' (outermost projection) and 'To covered car parking space and domestic outbuildings'. Row selection is by 'Height of wall' (not defined in the scheme).$q$, $q$mb_rr_rad48_road_setback$q$);
